export async function POST(req: NextRequest) {
  try {
    // 1. Authentication check
    const supabase = await createServerSupabaseClient()
    const { data: { user }, error: authError } = await supabase.auth.getUser()

    if (authError || !user) {
      return new Response(
        JSON.stringify({ error: 'Unauthorized - Please sign in to use AI assistant' }), 
        { status: 401, headers: { 'Content-Type': 'application/json' } }
      )
    }

    // 2. Rate limiting check
    const userKey = user.id
    const now = Date.now()
    const userLimit = rateLimitStore.get(userKey)

    if (userLimit) {
      if (now < userLimit.resetTime) {
        if (userLimit.count >= RATE_LIMIT) {
          return new Response(
            JSON.stringify({ error: 'Rate limit exceeded - Please try again later' }), 
            { status: 429, headers: { 'Content-Type': 'application/json' } }
          )
        }
        userLimit.count++
      } else {
        rateLimitStore.set(userKey, { count: 1, resetTime: now + RATE_LIMIT_WINDOW })
      }
    } else {
      rateLimitStore.set(userKey, { count: 1, resetTime: now + RATE_LIMIT_WINDOW })
    }

    // 3. Input validation
    const body = await req.json()
    const { messages } = body

    if (!messages || !Array.isArray(messages) || messages.length === 0) {
      return new Response(
        JSON.stringify({ error: 'Invalid request - Messages array required' }), 
        { status: 400, headers: { 'Content-Type': 'application/json' } }
      )
    }

    // Validate message structure and limit message length
    for (const message of messages) {
      if (!message.content || typeof message.content !== 'string') {
        return new Response(
          JSON.stringify({ error: 'Invalid message format' }), 
          { status: 400, headers: { 'Content-Type': 'application/json' } }
        )
      }

      if (message.content.length > 2000) {
        return new Response(
          JSON.stringify({ error: 'Message too long - Maximum 2000 characters' }), 
          { status: 400, headers: { 'Content-Type': 'application/json' } }
        )
      }
    }

    // 4. Generate AI response
    const result = streamText({
      model: openai('gpt-4o'), // Will use GPT-5 when available
      system: SYSTEM_PROMPT,
      messages,
      temperature: 0.7,
      maxTokens: 500,
    })

    return result.toDataStreamResponse()

  } catch (error) {
    console.error('Chat API error:', error)
    return new Response(
      JSON.stringify({ error: 'Internal server error' }), 
      { status: 500, headers: { 'Content-Type': 'application/json' } }
    )
  }
}

