import { cn } from "@/lib/utils"
import { GlassCard } from "./glass-card"
import { Badge } from "@/components/ui/badge"
import { MapPin, Calendar, Clock, DollarSign } from "lucide-react"
import { format } from "date-fns"

interface ListingCardProps {
  listing: {
    id: string
    title: string
    description: string | null
    location: string
    dates: any // JSON type from database
    timeslots: any // JSON type from database
    pay_min: number | null
    pay_max: number | null
    urgency: string | null
    status: string
    created_at: string
    org?: {
      org_name: string
    }
  }
  onClick?: () => void
  className?: string
}

export function ListingCard({ listing, onClick, className }: ListingCardProps) {
  const getUrgencyBadge = () => {
    if (!listing.urgency) return null

    const urgencyColors = {
      urgent: "bg-red-500/10 text-red-700 border-red-200",
      soon: "bg-orange-500/10 text-orange-700 border-orange-200",
      flexible: "bg-green-500/10 text-green-700 border-green-200"
    }

    return (
      <Badge className={cn("ml-auto", urgencyColors[listing.urgency as keyof typeof urgencyColors])}>
        {listing.urgency}
      </Badge>
    )
  }

  const formatPayRange = () => {
    if (!listing.pay_min && !listing.pay_max) return "Rate negotiable"
    if (listing.pay_min && listing.pay_max) {
      return `$${listing.pay_min} - $${listing.pay_max}/hr`
    }
    if (listing.pay_min) return `From $${listing.pay_min}/hr`
    return `Up to $${listing.pay_max}/hr`
  }

  return (
    <GlassCard
      className={cn(
        "cursor-pointer transition-all hover:scale-[1.02]",
        className
      )}
      onClick={onClick}
    >
      <div className="space-y-4">
        <div className="flex items-start justify-between">
          <div>
            <h3 className="text-xl font-semibold">{listing.title}</h3>
            {listing.org && (
              <p className="text-sm text-muted-foreground mt-1">
                {listing.org.org_name}
              </p>
            )}
          </div>
          {getUrgencyBadge()}
        </div>

        {listing.description && (
          <p className="text-muted-foreground line-clamp-2">
            {listing.description}
          </p>
        )}

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 text-sm">
          <div className="flex items-center gap-2 text-muted-foreground">
            <MapPin className="w-4 h-4" />
            <span>{listing.location}</span>
          </div>

          <div className="flex items-center gap-2 text-muted-foreground">
            <DollarSign className="w-4 h-4" />
            <span>{formatPayRange()}</span>
          </div>

          {listing.dates && Array.isArray(listing.dates) && listing.dates.length > 0 && (
            <div className="flex items-center gap-2 text-muted-foreground">
              <Calendar className="w-4 h-4" />
              <span>
                {listing.dates.length === 1 
                  ? format(new Date(listing.dates[0]), "MMM d, yyyy")
                  : `${listing.dates.length} dates`
                }
              </span>
            </div>
          )}

          <div className="flex items-center gap-2 text-muted-foreground">
            <Clock className="w-4 h-4" />
            <span>Posted {format(new Date(listing.created_at), "MMM d")}</span>
          </div>
        </div>

        <div className={cn(
          "flex items-center justify-between pt-3 border-t",
          listing.status === "active" ? "border-green-200" : "border-border"
        )}>
          <Badge variant={listing.status === "active" ? "default" : "secondary"}>
            {listing.status}
          </Badge>
        </div>
      </div>
    </GlassCard>
  )
}

"use client"

import { useState } from "react"
import { useRouter } from "next/navigation"
import Link from "next/link"
import { createClient } from "@/lib/supabase/client"
import { GlassCard } from "@/components/ui/glass-card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { ArrowLeft, Mail, Lock } from "lucide-react"
import { useForm } from "react-hook-form"

interface SignInForm {
  email: string
  password: string
}

export default function SignInPage() {
  const router = useRouter()
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const supabase = createClient()

  const { register, handleSubmit, formState: { errors } } = useForm<SignInForm>()

  const onSubmit = async (data: SignInForm) => {
    setIsLoading(true)
    setError(null)

    try {
      const { error: signInError } = await supabase.auth.signInWithPassword({
        email: data.email,
        password: data.password,
      })

      if (signInError) {
        setError(signInError.message)
        return
      }

      // Get user role to redirect appropriately
      const { data: { user } } = await supabase.auth.getUser()
      if (user) {
        const { data: userData } = await supabase
          .from('users')
          .select('role')
          .eq('id', user.id)
          .single()

        if (userData) {
          switch (userData.role) {
            case 'org':
              router.push('/org/dashboard')
              break
            case 'coach':
              router.push('/coach/dashboard')
              break
            case 'admin':
              router.push('/admin')
              break
            default:
              router.push('/')
          }
        }
      }
    } catch (err) {
      setError('An unexpected error occurred')
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <div className="min-h-[calc(100vh-4rem)] flex items-center justify-center p-4">
      <div className="w-full max-w-md">
        <Link 
          href="/" 
          className="inline-flex items-center text-sm text-muted-foreground hover:text-foreground mb-8"
        >
          <ArrowLeft className="w-4 h-4 mr-2" />
          Back to home
        </Link>

        <GlassCard className="p-8">
          <div className="text-center mb-8">
            <h1 className="text-2xl font-bold mb-2">Welcome back</h1>
            <p className="text-muted-foreground">
              Sign in to your CoachFlow account
            </p>
          </div>

          <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
            {error && (
              <div className="p-3 rounded-lg bg-destructive/10 text-destructive text-sm">
                {error}
              </div>
            )}

            <div className="space-y-2">
              <Label htmlFor="email">Email</Label>
              <div className="relative">
                <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                <Input
                  id="email"
                  type="email"
                  placeholder="you@example.com"
                  className="pl-10"
                  {...register("email", {
                    required: "Email is required",
                    pattern: {
                      value: /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$/i,
                      message: "Invalid email address"
                    }
                  })}
                />
              </div>
              {errors.email && (
                <p className="text-sm text-destructive">{errors.email.message}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="password">Password</Label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                <Input
                  id="password"
                  type="password"
                  placeholder="••••••••"
                  className="pl-10"
                  {...register("password", {
                    required: "Password is required",
                    minLength: {
                      value: 6,
                      message: "Password must be at least 6 characters"
                    }
                  })}
                />
              </div>
              {errors.password && (
                <p className="text-sm text-destructive">{errors.password.message}</p>
              )}
            </div>

            <div className="flex items-center justify-between">
              <Link 
                href="/auth/forgot-password" 
                className="text-sm text-primary hover:underline"
              >
                Forgot password?
              </Link>
            </div>

            <Button 
              type="submit" 
              className="w-full" 
              disabled={isLoading}
            >
              {isLoading ? "Signing in..." : "Sign in"}
            </Button>
          </form>

          <div className="mt-6 text-center text-sm">
            <span className="text-muted-foreground">Don't have an account? </span>
            <Link 
              href="/auth/sign-up" 
              className="text-primary hover:underline font-medium"
            >
              Sign up
            </Link>
          </div>
        </GlassCard>
      </div>
    </div>
  )
}

